def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for r, row in enumerate(grid):
        counts = {}
        for v in row:
            counts[v] = counts.get(v, 0) + 1
        sep, n = max(counts.items(), key=lambda x: x[1])
        if n >= w - 2 and n < w:
            gaps = [c for c, v in enumerate(row) if v != sep]
            if len(gaps) == 2:
                candidates.append((r, sep, gaps))
    top, sep, gaps = candidates[0]
    bottom = candidates[-1][0]
    left, right = gaps
    bg = grid[top][left]
    out = []
    for r in range(top, bottom + 1):
        if r in (top, bottom):
            out.append([bg if c in (left, right) else sep for c in range(left, right + 1)])
        else:
            out.append([sep] + grid[r][left + 1:right] + [sep])
    return out
